import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function readExplorerFile(e){return readFileSync(resolve(__dirname,"../../noakhali-peace-mission-explorer",e),"utf-8")}function readSearchIndex(){return readFileSync(resolve(__dirname,"../../search-index.js"),"utf-8")}describe("Noakhali Peace Mission Explorer — Page Structure",()=>{let e;beforeAll(()=>{e=readExplorerFile("index.html")}),it("contains a hero section with page title and kicker",()=>{expect(e).toContain('class="np-hero"'),expect(e).toContain("<h1>"),expect(e).toContain("Noakhali Peace Mission"),expect(e).toContain("Road to Partition"),expect(e).toContain("Gandhi")}),it("contains all required content sections from the issue",()=>{["overview","violence","arrival","villages","meetings","outreach","reactions","route","tensions","efforts","significance","timeline","references"].forEach(t=>{expect(e).toContain(`id="${t}"`),expect(e).toContain(`data-tab="${t}"`)})}),it("contains all required historical topics",()=>{["Bengal Political Context","Noakhali Violence","Gandhi's Arrival","Villages Visited","Peace Meetings","Community Outreach","Local Reactions","Partition Tensions","Continued Peace Efforts","Historical Significance","Timeline","References"].forEach(t=>{expect(e).toContain(t)})}),it("contains key historical details and figures",()=>{expect(e).toContain("6 Nov 1946"),expect(e).toContain("Chandpur"),expect(e).toContain("Ramganj"),expect(e).toContain("Dattapara"),expect(e).toContain("Do or Die"),expect(e).toContain("Noakhali"),expect(e).toContain("Bihar"),expect(e).toContain("October 1946"),expect(e).toContain("Suhrawardy"),expect(e).toContain("Calcutta")}),it("presents sensitive material respectfully",()=>{expect(e).toContain("A note on sensitivity"),expect(e).toContain("respect"),expect(e).toContain("care"),expect(e).toContain("never on graphic detail")}),it("has a semantic heading hierarchy (single h1, multiple h2s)",()=>{const t=(e.match(/<h1[\s>]/g)||[]).length,i=(e.match(/<h2[\s>]/g)||[]).length;expect(t).toBe(1),expect(i).toBeGreaterThanOrEqual(10)}),it("includes interactive features: route map, village markers, timeline, and peace milestones",()=>{expect(e).toContain('id="np-route-map"'),expect(e).toContain('id="np-interactive-timeline"'),expect(e).toContain("np-map-detail"),expect(e).toContain("Peace Meetings"),expect(e).toContain("milestones")}),it("links the shared stylesheet, page stylesheet, Leaflet, and script",()=>{expect(e).toContain('href="../../styles.css"'),expect(e).toContain('href="style.css"'),expect(e).toContain('src="script.js"'),expect(e).toContain("leaflet")}),it("references reliable historical sources",()=>{expect(e).toContain("britannica.com"),expect(e).toContain("wikipedia.org"),expect(e).toContain("Pyarelal"),expect(e).toContain("Guha"),expect(e).toContain("Yasmin Khan"),expect(e).toContain("Chatterji")})}),describe("Noakhali Peace Mission Explorer — Assets",()=>{it("includes a non-empty stylesheet themed for the subject",()=>{const e=readExplorerFile("style.css");expect(e.length).toBeGreaterThan(1e3),expect(e).toContain(".np-hero"),expect(e).toContain(".np-map"),expect(e).toContain(".np-timeline"),expect(e).toContain(".np-route-line")}),it("includes a valid interactive script with required functions",()=>{const e=readExplorerFile("script.js");expect(e).toContain("activateTab"),expect(e).toContain("initRouteMap"),expect(e).toContain("NP_ROUTE_POINTS"),expect(e).toContain("initTimeline"),expect(e).toContain("initThemeToggle"),expect(e).toContain("registerSearchItems"),expect(e).toContain("Journey"),expect(e).toContain("L.polyline"),expect(e).toContain("document.addEventListener('DOMContentLoaded'")})}),describe("Noakhali Peace Mission — Integration",()=>{it('is grouped under "Road to Partition" in the explorer page navigation',()=>{const e=readExplorerFile("index.html"),t=e.indexOf("Road to Partition ▾");expect(t).toBeGreaterThan(-1);const i=e.slice(t,t+900);expect(i).toContain("Gandhi's Noakhali Peace Mission"),expect(i).toContain("calcutta-1946-crisis-explorer/index.html")}),it("is added to the global search index under Road to Partition",()=>{const e=readSearchIndex();expect(e).toContain("Noakhali Peace Mission Explorer"),expect(e).toContain("Road to Partition"),expect(e).toContain("frontend/noakhali-peace-mission-explorer/index.html")}),it("is pre-cached for offline support",()=>{const e=readFileSync(resolve(__dirname,"../../sw.js"),"utf-8"),t=readFileSync(resolve(__dirname,"../../offline.html"),"utf-8");expect(e).toContain("./noakhali-peace-mission-explorer/index.html"),expect(e).toContain("./noakhali-peace-mission-explorer/style.css"),expect(e).toContain("./noakhali-peace-mission-explorer/script.js"),expect(t).toContain("/frontend/noakhali-peace-mission-explorer/")})});